    comp_section_stack: "\u0643\u0645 \u0623\u062f\u0627\u0629 \u062a\u062d\u062a\u0627\u062c \u0644\u0645\u0637\u0627\u0628\u0642\u0629 A.R.C.H.I.E.\u061f",
