    comp_stack_archie: "A.R.C.H.I.E.",
    comp_stack_archie_desc: "\u0645\u0646\u0635\u0629 \u0645\u0648\u062d\u062f\u0629 \u0648\u0627\u062d\u062f\u0629",
    comp_stack_missing: "\u0648\u0633\u062a\u0638\u0644 \u062a\u0641\u062a\u0642\u0631 \u0625\u0644\u0649 \u0631\u0641\u0627\u0647\u064a\u0629 \u0627\u0644\u0648\u0643\u0644\u0627\u0621\u060c \u062f\u0648\u0631\u0629 \u0627\u0644\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u062f\u0627\u0641\u0626\u060c \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u062d\u0633\u0628 \u0627\u0644\u0645\u062d\u0637\u0629\u060c \u0645\u0644\u0641\u0627\u062a \u0627\u0644\u0645\u0647\u0627\u0645\u060c \u0627\u0644\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0630\u0627\u062a\u064a \u0648\u062a\u0635\u0639\u064a\u062f Telegram.",
    comp_cat_orch_title: "\u0623\u0637\u0631 \u0627\u0644\u062a\u0646\u0633\u064a\u0642",
    comp_cat_orch_desc: "\u0645\u0643\u062a\u0628\u0627\u062a \u0644\u0628\u0646\u0627\u0621 \u0623\u0646\u0638\u0645\u0629 \u0645\u062a\u0639\u062f\u062f\u0629 \u0627\u0644\u0648\u0643\u0644\u0627\u0621. \u062a\u0643\u062a\u0628 \u0627\u0644\u0643\u0648\u062f\u060c \u062a\u062d\u062f\u062f \u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u062a\u0631\u0628\u0637 \u0627\u0644\u0648\u0643\u0644\u0627\u0621. \u0645\u062b\u0627\u0644\u064a \u0644\u0644\u0645\u0637\u0648\u0631\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0631\u064a\u062f\u0648\u0646 \u062a\u062d\u0643\u0645\u0627\u064b \u0643\u0627\u0645\u0644\u0627\u064b.",
    comp_cat_orch_edge: "\u0647\u0630\u0647 \u0645\u0643\u062a\u0628\u0627\u062a \u0644\u0644\u062a\u062c\u0645\u064a\u0639. ARCHIE \u0646\u0638\u0627\u0645 \u064a\u0639\u0645\u0644 \u0641\u0639\u0644\u064a\u0627\u064b \u2014 \u062a\u0648\u062c\u064a\u0647 GPU\u060c \u062a\u0634\u063a\u064a\u0644 \u062f\u0627\u0641\u0626\u060c \u0623\u0645\u0646 \u0645\u0627\u062f\u064a \u0648 39 \u0645\u0647\u0645\u0629 \u0645\u0633\u062a\u0642\u0644\u0629 \u062c\u0627\u0647\u0632\u0629. \u0644\u0627 \u062a\u062c\u0645\u064a\u0639 \u0645\u0637\u0644\u0648\u0628.",
    comp_cat_work_title: "\u0628\u0646\u0627\u0629 \u0633\u064a\u0631 \u0627\u0644\u0639\u0645\u0644",
    comp_cat_work_desc: "\u0645\u0646\u0635\u0627\u062a \u0645\u0631\u0626\u064a\u0629 \u0644\u0644\u0633\u062d\u0628 \u0648\u0627\u0644\u0625\u0641\u0644\u0627\u062a \u0644\u0631\u0628\u0637 LLMs \u0628\u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0648\u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a. \u0642\u0648\u064a\u0629 \u0644\u0644\u0641\u0631\u0642 \u0628\u062f\u0648\u0646 \u0643\u0648\u062f \u0648\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629.",
    comp_cat_work_edge: "\u0628\u0646\u0627\u0629 \u0633\u064a\u0631 \u0627\u0644\u0639\u0645\u0644 \u062a\u0631\u0628\u0637 \u0627\u0644\u0623\u0634\u064a\u0627\u0621. ARCHIE \u064a\u0646\u0633\u0642 23 \u0648\u0643\u064a\u0644\u0627\u064b \u0645\u0633\u062a\u0642\u0644\u0627\u064b \u0645\u0639 \u062a\u0648\u0632\u064a\u0639 \u0628\u0627\u0644\u0645\u062d\u0637\u0627\u062a\u060c \u0625\u062f\u0627\u0631\u0629 VRAM \u0648\u062a\u062d\u0633\u064a\u0646 \u0630\u0627\u062a\u064a \u2014 \u0642\u062f\u0631\u0627\u062a \u0644\u0627 \u064a\u0642\u062f\u0645\u0647\u0627 \u0623\u064a \u0628\u0646\u0627\u0621 \u0645\u0631\u0626\u064a.",
    comp_cat_code_title: "\u0648\u0643\u0644\u0627\u0621 \u0628\u0631\u0645\u062c\u0629 \u0645\u0633\u062a\u0642\u0644\u0648\u0646",
    comp_cat_code_desc: "\u0623\u062f\u0648\u0627\u062a \u0628\u0631\u0645\u062c\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u062a\u0643\u062a\u0628 \u0648\u062a\u0639\u062f\u0644 \u0648\u062a\u0635\u062d\u062d \u0627\u0644\u0643\u0648\u062f. \u062a\u062a\u0641\u0648\u0642 \u0641\u064a \u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0628\u0631\u0645\u062c\u064a\u0627\u062a \u0644\u0643\u0646\u0647\u0627 \u062a\u0631\u0643\u0632 \u062d\u0635\u0631\u064a\u0627\u064b \u0639\u0644\u0649 \u0627\u0644\u0643\u0648\u062f.",
    comp_cat_code_edge: "\u0648\u0643\u0644\u0627\u0621 \u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u064a\u0643\u062a\u0628\u0648\u0646 \u0643\u0648\u062f. ARCHIE \u0645\u0646\u0635\u0629 \u0639\u0645\u0644\u064a\u0627\u062a \u0645\u062a\u0639\u062f\u062f\u0629 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a \u2014 \u0623\u0645\u0646 \u0645\u0627\u062f\u064a\u060c \u0645\u0631\u0627\u0642\u0628\u0629 \u0634\u0628\u0643\u0627\u062a\u060c \u0630\u0643\u0627\u0621 \u062e\u0644\u0641\u064a \u0648\u062a\u0637\u0648\u064a\u0631 \u0630\u0627\u062a\u064a \u0644\u0643\u0648\u062f\u0647.",
    comp_cat_ent_title: "\u0645\u0646\u0635\u0627\u062a \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a",
    comp_cat_ent_desc: "\u0645\u0646\u0635\u0627\u062a \u0625\u0646\u062a\u0627\u062c \u0645\u062f\u0639\u0648\u0645\u0629 \u0645\u0646 \u0645\u0632\u0648\u062f\u064a\u0646 \u0643\u0628\u0627\u0631. \u0633\u062d\u0627\u0628\u064a\u0629 \u0623\u0648\u0644\u0627\u064b\u060c \u0628\u062d\u062c\u0645 \u0645\u0624\u0633\u0633\u064a\u060c \u0645\u0639 \u0628\u0646\u064a\u0629 \u062a\u062d\u062a\u064a\u0629 \u0645\u062f\u0627\u0631\u0629 \u0648\u0623\u0646\u0638\u0645\u0629 \u062a\u0643\u0627\u0645\u0644 \u0648\u0627\u0633\u0639\u0629.",
    comp_cat_ent_edge: "\u0645\u0646\u0635\u0627\u062a \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u062a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0627\u0644\u0633\u062d\u0627\u0628\u0629. ARCHIE \u064a\u0639\u0645\u0644 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0639\u0644\u0649 \u0623\u062c\u0647\u0632\u0629 \u0645\u062d\u0644\u064a\u0629 (128GB RAM\u060c Quadro M4000)\u060c \u0645\u0639 \u062d\u0648\u0643\u0645\u0629 \u0631\u0641\u0627\u0647\u064a\u0629 \u0627\u0644\u0648\u0643\u0644\u0627\u0621 \u0648\u0635\u0641\u0631 \u0627\u0639\u062a\u0645\u0627\u062f \u0639\u0644\u0649 \u0627\u0644\u0633\u062d\u0627\u0628\u0629.",
