    comp_hero_subtitle: "\u05e0\u05d3\u05e8\u05e9\u05d9\u05dd 7+ \u05db\u05dc\u05d9\u05dd \u05db\u05d3\u05d9 \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05dc\u05de\u05d4 \u05e9-ARCHIE \u05e2\u05d5\u05e9\u05d4 \u05d1\u05e4\u05dc\u05d8\u05e4\u05d5\u05e8\u05de\u05d4 \u05d0\u05d7\u05ea",
