    comp_section_category: "\u05d4\u05e9\u05d5\u05d5\u05d0\u05d4 \u05dc\u05e4\u05d9 \u05e7\u05d8\u05d2\u05d5\u05e8\u05d9\u05d4",
    comp_section_stack: "\u05db\u05de\u05d4 \u05db\u05dc\u05d9\u05dd \u05e0\u05d3\u05e8\u05e9\u05d9\u05dd \u05dc\u05d4\u05ea\u05d0\u05d9\u05dd \u05dc-A.R.C.H.I.E.?",
    comp_stack_intro: "\u05e4\u05dc\u05d8\u05e4\u05d5\u05e8\u05de\u05d4 \u05d0\u05d7\u05ea \u05de\u05d5\u05dc \u05d8\u05dc\u05d0\u05d9 \u05e9\u05dc \u05e9\u05d1\u05e2",
    comp_stack_archie: "A.R.C.H.I.E.",
    comp_stack_archie_desc: "\u05e4\u05dc\u05d8\u05e4\u05d5\u05e8\u05de\u05d4 \u05de\u05d0\u05d5\u05d7\u05d3\u05ea \u05d0\u05d7\u05ea",
    comp_stack_missing: "\u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05d9\u05d7\u05e1\u05e8\u05d5 \u05dc\u05da \u05e8\u05d5\u05d5\u05d7\u05ea \u05e1\u05d5\u05db\u05e0\u05d9\u05dd, \u05de\u05d7\u05d6\u05d5\u05e8 \u05d7\u05d9\u05d9\u05dd \u05d7\u05dd, \u05e9\u05d9\u05d2\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05ea\u05d7\u05e0\u05d4, \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9 \u05de\u05e9\u05d9\u05de\u05d4, \u05e9\u05d9\u05e4\u05d5\u05e8 \u05e2\u05e6\u05de\u05d9 \u05d5\u05d4\u05e1\u05dc\u05de\u05d4 \u05d1-Telegram.",
    comp_cat_orch_title: "\u05de\u05e1\u05d2\u05e8\u05d5\u05ea \u05ea\u05d6\u05de\u05d5\u05e8",
    comp_cat_orch_desc: "\u05e1\u05e4\u05e8\u05d9\u05d5\u05ea \u05dc\u05d1\u05e0\u05d9\u05d9\u05ea \u05de\u05e2\u05e8\u05db\u05d5\u05ea \u05e8\u05d1-\u05e1\u05d5\u05db\u05e0\u05d9\u05dd. \u05d0\u05ea\u05d4 \u05db\u05d5\u05ea\u05d1 \u05e7\u05d5\u05d3, \u05de\u05d2\u05d3\u05d9\u05e8 \u05ea\u05e4\u05e7\u05d9\u05d3\u05d9\u05dd \u05d5\u05de\u05d7\u05d1\u05e8 \u05e1\u05d5\u05db\u05e0\u05d9\u05dd. \u05d0\u05d9\u05d3\u05d9\u05d0\u05dc\u05d9 \u05dc\u05de\u05e4\u05ea\u05d7\u05d9\u05dd \u05e9\u05e8\u05d5\u05e6\u05d9\u05dd \u05e9\u05dc\u05d9\u05d8\u05d4 \u05de\u05dc\u05d0\u05d4.",
    comp_cat_orch_edge: "\u05d0\u05dc\u05d4 \u05e1\u05e4\u05e8\u05d9\u05d5\u05ea \u05dc\u05d4\u05e8\u05db\u05d1\u05d4. ARCHIE \u05d4\u05d5\u05d0 \u05de\u05e2\u05e8\u05db\u05ea \u05e4\u05e2\u05d9\u05dc\u05d4 \u2014 \u05e0\u05d9\u05ea\u05d5\u05d1 GPU, \u05d4\u05e4\u05e2\u05dc\u05d4 \u05d7\u05de\u05d4, \u05d0\u05d1\u05d8\u05d7\u05d4 \u05e4\u05d9\u05d6\u05d9\u05ea \u05d5-39 \u05de\u05e9\u05d9\u05de\u05d5\u05ea \u05d0\u05d5\u05d8\u05d5\u05e0\u05d5\u05de\u05d9\u05d5\u05ea \u05de\u05d5\u05db\u05e0\u05d5\u05ea. \u05dc\u05dc\u05d0 \u05d4\u05e8\u05db\u05d1\u05d4.",
    comp_cat_work_title: "\u05d1\u05d5\u05e0\u05d9 \u05ea\u05d4\u05dc\u05d9\u05db\u05d9 \u05e2\u05d1\u05d5\u05d3\u05d4",
    comp_cat_work_desc: "\u05e4\u05dc\u05d8\u05e4\u05d5\u05e8\u05de\u05d5\u05ea \u05d2\u05e8\u05d0\u05e4\u05d9\u05d5\u05ea \u05dc\u05d2\u05e8\u05d9\u05e8\u05d4 \u05d5\u05e9\u05d7\u05e8\u05d5\u05e8 \u05dc\u05d7\u05d9\u05d1\u05d5\u05e8 LLMs \u05dc\u05db\u05dc\u05d9\u05dd \u05d5\u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05e0\u05ea\u05d5\u05e0\u05d9\u05dd. \u05d7\u05d6\u05e7\u05d5\u05ea \u05dc\u05e6\u05d5\u05d5\u05ea\u05d9\u05dd \u05dc\u05dc\u05d0 \u05e7\u05d5\u05d3 \u05d5\u05dc\u05d9\u05e6\u05d9\u05e8\u05ea \u05d0\u05d1-\u05d8\u05d9\u05e4\u05d5\u05e1 \u05de\u05d4\u05d9\u05e8\u05d4.",
    comp_cat_work_edge: "\u05d1\u05d5\u05e0\u05d9 \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d3\u05d1\u05e8\u05d9\u05dd. ARCHIE \u05de\u05ea\u05d6\u05de\u05e8 23 \u05e1\u05d5\u05db\u05e0\u05d9\u05dd \u05d0\u05d5\u05d8\u05d5\u05e0\u05d5\u05de\u05d9\u05d9\u05dd \u05e2\u05dd \u05e9\u05d9\u05d2\u05d5\u05e8 \u05dc\u05e4\u05d9 \u05ea\u05d7\u05e0\u05d4, \u05e0\u05d9\u05d4\u05d5\u05dc VRAM \u05d5\u05e9\u05d9\u05e4\u05d5\u05e8 \u05e2\u05e6\u05de\u05d9 \u2014 \u05d9\u05db\u05d5\u05dc\u05d5\u05ea \u05e9\u05d0\u05e3 \u05d1\u05d5\u05e0\u05d4 \u05d2\u05e8\u05e4\u05d9 \u05dc\u05d0 \u05de\u05e6\u05d9\u05e2.",
    comp_cat_code_title: "\u05e1\u05d5\u05db\u05e0\u05d9 \u05e7\u05d9\u05d3\u05d5\u05d3 \u05d0\u05d5\u05d8\u05d5\u05e0\u05d5\u05de\u05d9\u05d9\u05dd",
    comp_cat_code_desc: "\u05db\u05dc\u05d9 AI \u05e9\u05db\u05d5\u05ea\u05d1\u05d9\u05dd, \u05e2\u05d5\u05e8\u05db\u05d9\u05dd \u05d5\u05de\u05d0\u05ea\u05e8\u05d9\u05dd \u05e7\u05d5\u05d3. \u05de IDE \u05de\u05dc\u05d0\u05d9\u05dd \u05e2\u05d3 \u05e1\u05d5\u05db\u05e0\u05d9 \u05d8\u05e8\u05de\u05d9\u05e0\u05dc, \u05d4\u05dd \u05de\u05e6\u05d8\u05d9\u05d9\u05e0\u05d9\u05dd \u05d1\u05d4\u05e0\u05d3\u05e1\u05ea \u05ea\u05d5\u05db\u05e0\u05d4 \u05d0\u05da \u05de\u05ea\u05de\u05e7\u05d3\u05d9\u05dd \u05d1\u05e7\u05d5\u05d3 \u05d1\u05dc\u05d1\u05d3.",
    comp_cat_code_edge: "\u05e1\u05d5\u05db\u05e0\u05d9 \u05e7\u05d9\u05d3\u05d5\u05d3 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05e7\u05d5\u05d3. ARCHIE \u05d4\u05d9\u05d0 \u05e4\u05dc\u05d8\u05e4\u05d5\u05e8\u05de\u05ea \u05ea\u05e4\u05e2\u05d5\u05dc \u05e8\u05d1-\u05ea\u05d7\u05d5\u05de\u05d9\u05ea \u2014 \u05d0\u05d1\u05d8\u05d7\u05d4 \u05e4\u05d9\u05d6\u05d9\u05ea, \u05e0\u05d9\u05d8\u05d5\u05e8 \u05e8\u05e9\u05ea, \u05de\u05d5\u05d3\u05d9\u05e2\u05d9\u05df \u05e8\u05e7\u05e2\u05d9 \u05d5\u05d4\u05ea\u05e4\u05ea\u05d7\u05d5\u05ea \u05e2\u05e6\u05de\u05d9\u05ea \u05e9\u05dc \u05d4\u05e7\u05d5\u05d3.",
