function compSwitchLang(lang) {
    document.querySelectorAll('[data-i18n]').forEach(function(el) {
        var key = el.getAttribute('data-i18n');
        if (COMP_TRANSLATIONS[lang] && COMP_TRANSLATIONS[lang][key]) {
            el.textContent = COMP_TRANSLATIONS[lang][key];
        }
    });
    document.documentElement.dir = (lang === 'ar' || lang === 'he') ? 'rtl' : 'ltr';
    document.documentElement.lang = lang;
    document.getElementById('compLangMenu').style.display = 'none';
    localStorage.setItem('ke_lang', lang);
    document.querySelectorAll('.comp-lang-menu button').forEach(function(btn) {
        btn.classList.remove('active');
    });
    var activeBtn = document.querySelector('.comp-lang-menu button[onclick*="' + lang + '"]');
    if (activeBtn) activeBtn.classList.add('active');
}

function toggleCompLangMenu() {
    var menu = document.getElementById('compLangMenu');
    menu.style.display = menu.style.display === 'none' ? 'block' : 'none';
}

document.addEventListener('click', function(e) {
    var selector = document.querySelector('.comp-lang-selector');
    if (selector && !selector.contains(e.target)) {
        document.getElementById('compLangMenu').style.display = 'none';
    }
});

document.addEventListener('DOMContentLoaded', function() {
    var saved = localStorage.getItem('ke_lang');
    if (saved && saved !== 'en') compSwitchLang(saved);
});
